function dancepad_workflow(){document.querySelectorAll(".dan-workflow").forEach(function(element){if(typeof element._dancepadWorkflowCleanup==="function"){element._dancepadWorkflowCleanup()}
element.removeAttribute("data-flickering");var steps=Array.from(element.querySelectorAll(".dan-workflow__step"));if(!steps.length){return}
var progressDuration=parseFloat(element.dataset.progressDur);if(Number.isNaN(progressDuration)||progressDuration<=0){progressDuration=1}
var lineDuration=parseFloat(element.dataset.lineDur);if(Number.isNaN(lineDuration)||lineDuration<=0){lineDuration=2.75}
var shouldLoop=element.dataset.loop==="1";element.style.setProperty("--dan-wf-progress-dur",progressDuration+"s");var timeoutIds=[];var observer=null;var isStopped=!1;function queue(callback,delay){var timeoutId=window.setTimeout(function(){timeoutIds=timeoutIds.filter(function(id){return id!==timeoutId});callback()},delay);timeoutIds.push(timeoutId);return timeoutId}
function clearQueuedActions(){timeoutIds.forEach(function(timeoutId){window.clearTimeout(timeoutId)});timeoutIds=[]}
function resetAll(){steps.forEach(function(step){step.classList.remove("is-active","is-completed");var fill=step.querySelector(".dan-workflow__line-fill");if(fill){fill.style.transition="none";fill.style.height="0";void fill.offsetHeight}})}
function run(index){if(isStopped||!element.isConnected){return}
if(index>=steps.length){if(shouldLoop){queue(function(){if(isStopped){return}
resetAll();queue(function(){run(0)},300)},1000)}
return}
var step=steps[index];step.classList.add("is-active");queue(function(){if(isStopped||!element.isConnected){return}
step.classList.add("is-completed");var fill=step.querySelector(".dan-workflow__line-fill");if(fill){fill.style.transition="height "+lineDuration+"s linear";fill.style.height="100%";queue(function(){run(index+1)},lineDuration*1000)}else{queue(function(){run(index+1)},350)}},(progressDuration+0.5)*1000)}
observer=new IntersectionObserver(function(entries){if(entries[0]&&entries[0].isIntersecting){observer.disconnect();observer=null;queue(function(){run(0)},500)}},{threshold:0.1});observer.observe(element);element._dancepadWorkflowCleanup=function(){isStopped=!0;if(observer){observer.disconnect()}
clearQueuedActions();resetAll();delete element._dancepadWorkflowCleanup}})}
document.addEventListener("DOMContentLoaded",function(){if(typeof bricksIsFrontend==="undefined"||bricksIsFrontend){dancepad_workflow()}})